import { defineStore } from 'pinia';
import http from '../../../shared/infrastructure/http-common';
import { createTask } from '../domain/task.entity';
const getTaskImage = (description) => {
    const text = description.toLowerCase();

    if (text.includes('aceite')) {
        return 'data:image/jpeg;base64,';}
    if (text.includes('freno')) {
        return 'data:image/jpeg;base64,';
    }
    if (text.includes('motor')) {
        return 'data:image/jpeg;base64,';
    }
    if (text.includes('pastilla')){
        return 'https://www.google.com/imgres?q=ajuste%20pastillas%20de%20freno&imgurl=https%3A%2F%2Fsiempreauto.com%2Fwp-content%2Fuploads%2Fsites%2F9%2F2023%2F12%2Fshutterstock_2177571801.jpg%3Fw%3D4096&imgrefurl=https%3A%2F%2Fsiempreauto.com%2Fpastillas-de-freno-como-ajustarlas%2F&docid=o-J8fmldeb3OfM&tbnid=p1Q8mEmaNKjn_M&vet=12ahUKEwiZ-NmktLCUAxXfLbkGHYeNBTgQnPAOegQIGRAB..i&w=4096&h=3072&hcb=2&itg=1&ved=2ahUKEwiZ-NmktLCUAxXfLbkGHYeNBTgQnPAOegQIGRAB'
    }
    if (text.includes('batería')) {
        return 'https://www.google.com/imgres?q=arreglo%20de%20baterias%20en%20un%20taller%20automotriz&imgurl=https%3A%2F%2Fwww.autodepot.mx%2Fwp-content%2Fuploads%2F2017%2F06%2Fsistema-electrico-870x580-02.jpg&imgrefurl=https%3A%2F%2Fwww.autodepot.mx%2Fprojects%2Fbaterias%2F&docid=YSkYZXQTaTNlbM&tbnid=u_F5NVqwXSnEXM&vet=12ahUKEwjMtPzMtLCUAxVBLLkGHYGPOYkQnPAOegQIFxAB..i&w=870&h=580&hcb=2&ved=2ahUKEwjMtPzMtLCUAxVBLLkGHYGPOYkQnPAOegQIFxAB';
    }
    if (text.includes('pintura')) {
        return 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSjXdeOBmX-QwKoswzCrK3hvqoj3GwoSrKnFw&s'
    }
    if (text.includes('engrase')) {
        return 'data:image/jpeg;base64,'
    }
    if (text.includes('limpieza')){
        return 'https://thf.bing.com/th/id/OIP.Wfc3b2yZCubxMTFeTPfKjQHaEJ?w=266&h=180&c=7&r=0&o=7&cb=thfc1&pid=1.7&rm=3'
    }
    if (text.includes('llanta')) {
        return 'data:image/jpeg;base64,';}


    return 'https://images.unsplash.com/photo-1517524206127-48bbd363f3d7';
};
export const useTaskStore = defineStore('task', {
    state: () => ({
        tasks: [],
        loading: false
    }),

    actions: {
        async fetchAllTasks() {
            this.loading = true;

            try {
                const response = await http.get('/tasks');
                this.tasks = response.data.map((task) => createTask(task));
            } finally {
                this.loading = false;
            }
        },

        async fetchTasksByOrder(workOrderId) {
            this.loading = true;

            try {
                const response = await http.get(`/tasks?workOrderId=${workOrderId}`);
                this.tasks = response.data.map((task) => createTask(task));
            } finally {
                this.loading = false;
            }
        },

        async addTask(taskData) {
            /*const newTask = createTask(taskData);*/
            const photo = getTaskImage(taskData.description);

            const newTask = createTask({
                ...taskData,
                photo
            });
            const response = await http.post('/tasks', newTask);
            this.tasks.push(createTask(response.data));
            return response.data;
        },


        async updateTask(id, taskData) {
            const response = await http.put(`/tasks/${id}`, createTask(taskData));
            const index = this.tasks.findIndex((task) => String(task.id) === String(id));

            if (index !== -1) {
                this.tasks.splice(index, 1, createTask(response.data));
            }

            return response.data;
        },

        async updateTaskStatus(id, newStatus) {
            const response = await http.patch(`/tasks/${id}`, { status: newStatus });
            const index = this.tasks.findIndex((task) => String(task.id) === String(id));

            if (index !== -1) {
                this.tasks.splice(index, 1, createTask(response.data));
            }

            return response.data;
        },

        async deleteTask(id) {
            await http.delete(`/tasks/${id}`);
            this.tasks = this.tasks.filter((task) => String(task.id) !== String(id));
        }
    }
});